              alt="A quiet lakeside cabin surrounded by trees at golden hour"
            >
          </figure>
          <div class="actions" aria-label="Image actions">
            <button class="button button-primary" type="button">Download</button>
            <button class="button button-danger trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
              Delete image
            </button>
          </div>
        </div>

        <div class="details-panel">
          <div>
            <p class="eyebrow">Library image</p>
            <h1 id="page-title">Golden hour retreat</h1>
          </div>

          <p class="description">
            A saved preview from your travel inspiration library. Review the details below before making permanent changes.
          </p>

          <dl class="meta-grid" aria-label="Image details">
            <div class="meta-row">
              <dt>Type</dt>
              <dd>Photo</dd>
            </div>
            <div class="meta-row">
              <dt>Size</dt>
              <dd>4.8 MB</dd>
            </div>
            <div class="meta-row">
              <dt>Added</dt>
              <dd>Today</dd>
            </div>
          </dl>

          <p class="status-message" id="status-message" aria-live="polite"></p>
        </div>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form class="dialog-card" method="dialog">
      <div class="dialog-header">
        <div class="dialog-title-group">
          <div class="warning-mark" aria-hidden="true">!</div>
          <div>
            <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
            <p class="dialog-description" id="dialog-description">
              This will remove "Golden hour retreat" from your library. This action cannot be undone.
            </p>
          </div>
        </div>
        <button class="icon-button" value="cancel" type="submit" aria-label="Close dialog">&times;</button>
      </div>

      <div class="dialog-actions">
        <button class="button button-secondary" value="cancel" type="submit">Cancel</button>
        <button class="button button-danger" id="confirm-delete" value="confirm" type="submit">
          Yes, delete it
        </button>
      </div>
    </form>
  </dialog>

  <script>
    const previewCard = document.querySelector(".preview-card");
    const deleteButton = document.querySelector(".trigger");
    const dialog = document.querySelector("#delete-dialog");
    const confirmDeleteButton = document.querySelector("#confirm-delete");
    const statusMessage = document.querySelector("#status-message");

    deleteButton.addEventListener("click", () => {
      dialog.showModal();
    });

    confirmDeleteButton.addEventListener("click", () => {
      previewCard.classList.add("is-deleted");
      deleteButton.disabled = true;
      deleteButton.textContent = "Image deleted";
      statusMessage.textContent = "The image has been deleted from your library.";
    });
  </script>
</body>
